CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, route TEXT NOT NULL, category TEXT NOT NULL, audience TEXT NOT NULL, provider_id TEXT, state TEXT NOT NULL, created_at INTEGER NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS recipients(message_id TEXT NOT NULL, uid TEXT NOT NULL, PRIMARY KEY(message_id,uid));
CREATE INDEX IF NOT EXISTS recipient_uid ON recipients(uid,message_id);
CREATE TABLE IF NOT EXISTS rank_members(uid TEXT PRIMARY KEY, academic_year INTEGER NOT NULL, alias TEXT NOT NULL, verified INTEGER NOT NULL, opt_out INTEGER NOT NULL, checked_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rank_group ON rank_members(academic_year,verified,opt_out);
CREATE TABLE IF NOT EXISTS rank_privacy(uid TEXT PRIMARY KEY, alias TEXT NOT NULL, opt_out INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rank_leases(uid TEXT PRIMARY KEY, academic_year INTEGER NOT NULL, session TEXT NOT NULL, last INTEGER NOT NULL, active INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 0, operation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rank_sessions(uid TEXT NOT NULL, academic_year INTEGER NOT NULL, session TEXT NOT NULL, seconds INTEGER NOT NULL, closed INTEGER NOT NULL, PRIMARY KEY(uid,academic_year,session));
CREATE TABLE IF NOT EXISTS rank_days(uid TEXT NOT NULL, academic_year INTEGER NOT NULL, day TEXT NOT NULL, seconds INTEGER NOT NULL, completed INTEGER NOT NULL, PRIMARY KEY(uid,academic_year,day));
CREATE INDEX IF NOT EXISTS rank_period ON rank_days(academic_year,day);
CREATE TABLE IF NOT EXISTS study_events(uid TEXT NOT NULL, id TEXT NOT NULL, fingerprint TEXT NOT NULL, received_at INTEGER NOT NULL, PRIMARY KEY(uid,id));
CREATE TABLE IF NOT EXISTS rank_revision(id INTEGER PRIMARY KEY, version INTEGER NOT NULL);
INSERT OR IGNORE INTO rank_revision(id,version) VALUES(1,0);
CREATE TRIGGER IF NOT EXISTS rank_member_insert AFTER INSERT ON rank_members BEGIN UPDATE rank_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS rank_member_update AFTER UPDATE ON rank_members BEGIN UPDATE rank_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS rank_privacy_insert AFTER INSERT ON rank_privacy BEGIN UPDATE rank_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS rank_privacy_update AFTER UPDATE ON rank_privacy BEGIN UPDATE rank_revision SET version=version+1 WHERE id=1; END;
CREATE TABLE IF NOT EXISTS rank_boards(academic_year INTEGER NOT NULL, period TEXT NOT NULL, generation TEXT NOT NULL, updated_at INTEGER NOT NULL, revision INTEGER NOT NULL, day TEXT NOT NULL, PRIMARY KEY(academic_year,period));
CREATE TABLE IF NOT EXISTS rank_entries(generation TEXT NOT NULL, uid TEXT NOT NULL, alias TEXT NOT NULL, academicYear INTEGER NOT NULL, verifiedMinutes INTEGER NOT NULL, sessions INTEGER NOT NULL, score INTEGER NOT NULL, rank INTEGER NOT NULL, PRIMARY KEY(generation,uid));
CREATE INDEX IF NOT EXISTS board_page ON rank_entries(generation,rank);
